```sql
/* Получаем уникальные города, в которых находятся объекты аренды (студенты) */
SELECT DISTINCT s."city"
FROM "students" AS s
WHERE s."city" IS NOT NULL;
```

```sql
/* Получаем требуемый уровень образования для вакансии AI Researcher */
SELECT DISTINCT d."degree_level"
FROM "degrees" d
WHERE d."job_post" = 'AI Researcher';
```

```sql
/* Получаем требуемую сертификацию для вакансии AI Researcher */
SELECT DISTINCT d."certification"
FROM "degrees" d
WHERE d."job_post" = 'AI Researcher';
```

```sql
/* Находим город и должность с минимальной зарплатой */
SELECT "city", "job" FROM (
    SELECT "city", "job", ROW_NUMBER() OVER (ORDER BY "salary" ASC) AS rn
    FROM "jobs"
) t
WHERE rn = 1;
```

